-- Aquagram — 0059: Tür görselleri 11. parti (363–400 arası 38 tür, 43 görsel; 362 eksik)
update public.species s set images = (select array_agg('https://aquagram.com.tr/media/tur/' || v.slug || '-' || i || '.webp' order by i) from generate_series(1, v.adet) i)
from (values ('farlowella-acus',1),('hara-jerdoni',1),('hypancistrus-contradens',1),('hypancistrus-sp-l260',1),('hypancistrus-zebra',1),('kryptopterus-vitreolus',1),('microglanis-iheringi',1),('mystus-leucophasis',1),('otocinclus-affinis',1),('otocinclus-macrospilus',1),('panaqolus-maccus',1),('panaque-nigrolineatus',1),('phractocephalus-hemioliopterus',1),('pimelodus-pictus',1),('platydoras-armatulus',1),('pseudomystus-siamensis',1),('pseudoplatystoma-fasciatum',2),('rineloricaria-lanceolata',1),('synodontis-eupterus',1),('synodontis-multipunctatus',1),('synodontis-nigriventris',1),('synodontis-petricola',1),('aphyosemion-australe',2),('aphyosemion-bitaeniatum',2),('aphyosemion-bivittatum',1),('aphyosemion-gabunense',2),('aphyosemion-ogoense',1),('aphyosemion-striatum',1),('aplocheilus-lineatus',1),('aplocheilus-panchax',1),('austrofundulus-limnaeus',1),('austrolebias-nigripinnis',1),('epiplatys-annulatus',2),('epiplatys-dageti',1),('epiplatys-sexfasciatus',1),('fundulopanchax-cinnamomeus',1),('fundulopanchax-filamentosus',1),('fundulopanchax-gardneri',1)) as v(slug, adet)
where s.slug = v.slug;
